import subprocess, sys, json
def run(src, args=None, env=None):
    a = ['/workspace/executable','-'] if args is None else ['/workspace/executable']+args
    import os
    e = dict(os.environ)
    e['CLICOLOR']='0'
    if env: e.update(env)
    p = subprocess.run(a, input=src.encode(), capture_output=True, env=e)
    return p.returncode, p.stdout.decode('utf-8','replace'), p.stderr.decode('utf-8','replace')
def show(src, args=None, env=None):
    c,o,er = run(src,args,env)
    print("IN : "+repr(src))
    print("OUT: "+repr(o))
    if er: print("ERR: "+repr(er))
    print("EXIT: %d"%c)
    print("-"*60)
if __name__=='__main__':
    for s in sys.stdin.read().split('\n\x00\n'):
        if s: show(s)
